<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>State of the Web 2020–2025</title>
    <link href="https://api.fontshare.com/v2/css?f[]=manrope@800,600,400&f[]=satoshi@700,500,400&display=swap" rel="stylesheet">
    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           =========================================== */
        :root {
            --bg-primary: #0a0f1c;
            --bg-secondary: #111827;
            --card-bg: rgba(30, 41, 59, 0.7);
            --text-primary: #ffffff;
            --text-secondary: #94a3b8;
            --accent: #3b82f6;
            --accent-glow: rgba(59, 130, 246, 0.3);
            --accent-success: #10b981;

            --font-display: 'Manrope', sans-serif;
            --font-body: 'Satoshi', sans-serif;

            --title-size: clamp(2.5rem, 5.5vw, 4.5rem);
            --h2-size: clamp(1.8rem, 3.5vw, 3rem);
            --h3-size: clamp(1.2rem, 2vw, 2rem);
            --body-size: clamp(0.9rem, 1.4vw, 1.25rem);
            --small-size: clamp(0.8rem, 1.1vw, 1rem);

            --slide-padding: clamp(2rem, 4vw, 4rem);
            --content-gap: clamp(1.5rem, 2.5vw, 2.5rem);
            --element-gap: clamp(0.5rem, 1vw, 1rem);

            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* --- VIEWPORT BASE --- */
        html, body {
            height: 100%;
            overflow-x: hidden;
            background-color: var(--bg-primary);
            color: var(--text-primary);
            font-family: var(--font-body);
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: auto; /* auto to ensure instant snap for screenshot tool */
        }
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            box-sizing: border-box;
        }
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
            box-sizing: border-box;
            z-index: 2;
        }
        .container {
            max-width: min(90vw, 1400px);
            width: 100%;
            margin: 0 auto;
        }
        .feature-list, .bullet-list {
            gap: clamp(0.6rem, 1.5vh, 1.2rem);
            display: flex;
            flex-direction: column;
            list-style: none;
            padding: 0;
            margin: 0;
        }
        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.5;
            position: relative;
            padding-left: 1.8rem;
        }
        .bullet-list li::before {
            content: "→";
            position: absolute;
            left: 0;
            color: var(--accent);
            font-weight: bold;
        }
        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 400px), 1fr));
            gap: clamp(1rem, 3vw, 3rem);
            align-items: center;
        }
        .grid-2 {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1.5rem, 4vw, 4rem);
            align-items: center;
            height: 100%;
        }
        img, .image-container {
            max-width: 100%;
            max-height: min(60vh, 500px);
            object-fit: contain;
            border-radius: 8px;
        }
        h1, h2, h3 {
            font-family: var(--font-display);
            line-height: 1.2;
            font-weight: 800;
            margin: 0 0 var(--element-gap) 0;
        }
        h1 { 
            font-size: var(--title-size); 
            background: linear-gradient(135deg, #fff, #94a3b8); 
            -webkit-background-clip: text; 
            -webkit-text-fill-color: transparent; 
        }
        h2 { font-size: var(--h2-size); }
        p { 
            font-size: var(--body-size); 
            line-height: 1.6; 
            color: var(--text-secondary); 
            margin: 0 0 var(--content-gap) 0; 
        }

        /* Stats */
        .stat-card {
            background: var(--card-bg);
            padding: var(--content-gap);
            border-radius: 16px;
            border: 1px solid rgba(255, 255, 255, 0.05);
            box-shadow: 0 10px 30px rgba(0,0,0,0.2);
            display: flex;
            flex-direction: column;
            justify-content: center;
        }
        .stat-value {
            font-size: clamp(3rem, 7vw, 5.5rem);
            font-family: var(--font-display);
            font-weight: 800;
            color: var(--accent);
            line-height: 1;
            margin-bottom: 0.5rem;
        }
        .stat-label {
            font-size: var(--h3-size);
            color: #fff;
            font-weight: 600;
        }
        .stat-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.5rem;
            line-height: 1.4;
        }

        /* Images */
        .chart-img {
            width: 100%;
            border-radius: 12px;
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.1);
            background: #fff;
        }

        /* Background decorations */
        .bg-glow {
            position: absolute;
            width: 60vw;
            height: 60vw;
            background: radial-gradient(circle, var(--accent-glow) 0%, transparent 60%);
            top: -30vw;
            right: -30vw;
            border-radius: 50%;
            z-index: 1;
            pointer-events: none;
        }

        /* Animations */
        .reveal {
            opacity: 0;
            transform: translateY(30px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }
        .reveal:nth-child(1) { transition-delay: 0.1s; }
        .reveal:nth-child(2) { transition-delay: 0.2s; }
        .reveal:nth-child(3) { transition-delay: 0.3s; }
        .reveal:nth-child(4) { transition-delay: 0.4s; }
        .reveal:nth-child(5) { transition-delay: 0.5s; }
    </style>
</head>
<body>
    <!-- Slide 1: Title -->
    <section class="slide" id="title-slide">
        <div class="bg-glow"></div>
        <div class="slide-content container" style="text-align: center; align-items: center;">
            <h1 class="reveal">State of the Web 2020–2025</h1>
            <h2 class="reveal" style="color: var(--accent); margin-bottom: 2rem;">Tracking Page Weight, Protocols & Security at Scale</h2>
            <div class="reveal stat-card" style="padding: 1.5rem 3rem; background: rgba(0,0,0,0.3); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,0.1);">
                <p style="font-size: var(--h3-size); color: #fff; margin-bottom: 0.5rem; font-weight: 600;">HTTP Archive Trends</p>
                <p style="margin: 0; color: var(--accent-success); font-family: var(--font-display); font-weight: 600;">Jan 2020 – Mar 2026</p>
            </div>
        </div>
    </section>

    <!-- Slide 2: Sample Size -->
    <section class="slide" id="sample-size-growth">
        <div class="slide-content container">
            <h2 class="reveal">Crawl Sample Size Tripled</h2>
            <p class="reveal">From ~5M to 16M Desktop URLs Since 2020</p>
            <div class="grid-2 reveal">
                <div style="display: flex; flex-direction: column; justify-content: center;">
                    <ul class="bullet-list">
                        <li><strong>Dramatic Growth:</strong> A sharp jump in URL coverage occurred around mid-2022.</li>
                        <li><strong>Current Plateau:</strong> The sample size has stabilized near 16M desktop and 12.5M mobile URLs.</li>
                        <li><strong>Significance:</strong> The massive scale of tracking guarantees high confidence in global web architectural trends.</li>
                    </ul>
                </div>
                <div>
                    <img src="assets/figure_1.jpg" alt="Timeseries of Sample Size" class="chart-img">
                </div>
            </div>
        </div>
    </section>

    <!-- Slide 3: Page Weight -->
    <section class="slide" id="page-weight-trends">
        <div class="slide-content container">
            <h2 class="reveal">Median Page Weight Climbs Steadily</h2>
            <p class="reveal">Desktop approaching ~2,000 KB per page</p>
            <div class="grid-2 reveal">
                <div style="display: flex; flex-direction: column; gap: 2rem;">
                    <ul class="bullet-list">
                        <li>Desktop median climbed from ~1,600 KB to ~2,000 KB.</li>
                        <li>Mobile tracks slightly lower but mirrors the ~25% upward trend over five years.</li>
                        <li><strong>The Long Tail:</strong> The 75th-percentile desktop page now exceeds 4,000 KB.</li>
                    </ul>
                    <div class="stat-card" style="padding: 1.5rem;">
                        <div class="stat-label">Total Kilobytes (Desktop Median)</div>
                        <div class="stat-value" style="font-size: 3.5rem;">~2,000 KB <span style="font-size: 1.8rem; color: #ef4444; vertical-align: middle;">▲ 25%</span></div>
                    </div>
                </div>
                <div>
                    <img src="assets/figure_2.jpg" alt="Timeseries of Total Kilobytes" class="chart-img">
                </div>
            </div>
        </div>
    </section>

    <!-- Slide 4: Requests & Connections -->
    <section class="slide" id="requests-and-connections">
        <div class="slide-content container">
            <h2 class="reveal">76 Requests/Page While TCP Connections Drop</h2>
            <p class="reveal">Network multiplexing efficiency outpaces standard request volume growth</p>
            <div class="grid-2 reveal">
                <div style="display: flex; flex-direction: column; gap: 1.5rem;">
                    <div class="stat-card">
                        <div class="stat-label">Desktop Requests</div>
                        <div class="stat-value">76</div>
                        <div class="stat-desc">▲ 2.7% since 2020 (Mobile requests at 71)</div>
                    </div>
                    <div class="stat-card">
                        <div class="stat-label">TCP Connections (Median)</div>
                        <div class="stat-value" style="color: var(--accent-success);">12.0</div>
                        <div class="stat-desc">▼ 14.3% since 2020 (Down from ~15 connections)</div>
                    </div>
                </div>
                <div>
                    <img src="assets/figure_3.jpg" alt="Timeseries of TCP Connections" class="chart-img">
                </div>
            </div>
        </div>
    </section>

    <!-- Slide 5: HTTPS -->
    <section class="slide" id="https-near-universal">
        <div class="slide-content container" style="text-align: center; align-items: center;">
            <h2 class="reveal">Encryption Is Now the Default</h2>
            <p class="reveal">Plaintext HTTP is effectively extinct on the modern web</p>
            <div class="stat-card reveal" style="margin: 3rem auto; max-width: 800px; padding: 4rem;">
                <div class="stat-value" style="font-size: clamp(5rem, 12vw, 9rem);">99.2%+</div>
                <div class="stat-label" style="font-size: var(--h2-size);">HTTPS Requests</div>
                <div class="stat-desc" style="font-size: var(--body-size); margin-top: 1.5rem; max-width: 600px; margin-left: auto; margin-right: auto;">
                    Up ~20 percentage points from ~80% in early 2020.<br>Mobile tracking is virtually identical at 99.1%.
                </div>
            </div>
        </div>
    </section>

    <!-- Slide 6: HTTP/2 & HTTP/3 -->
    <section class="slide" id="http2-http3-adoption">
        <div class="slide-content container">
            <h2 class="reveal">Protocol Shifts: HTTP/3 Support Surges</h2>
            <p class="reveal">HTTP/2 holds flat while HTTP/3 rapidly absorbs new protocol adoption</p>
            <div class="grid reveal" style="margin-top: 3rem;">
                <div class="stat-card" style="padding: 3rem;">
                    <div class="stat-label" style="font-size: var(--h2-size);">HTTP/2 Requests</div>
                    <div class="stat-value" style="color: #fff; margin: 1rem 0;">58.6%</div>
                    <div class="stat-desc" style="font-size: var(--body-size);">Relatively flat growth on Desktop.<br>It absorbs legacy HTTP/1.1 traffic while losing cutting-edge share to HTTP/3.</div>
                </div>
                <div class="stat-card" style="padding: 3rem; border-color: var(--accent);">
                    <div class="stat-label" style="font-size: var(--h2-size);">HTTP/3 Support</div>
                    <div class="stat-value" style="margin: 1rem 0;">38.7%</div>
                    <div class="stat-desc" style="font-size: var(--body-size);">Exploded from near-zero in 2020.<br><span style="opacity:0.7;">*Note: Metric represents support capability, as fresh Chrome instances default to HTTP/2.</span></div>
                </div>
            </div>
        </div>
    </section>

    <!-- Slide 7: Font Display -->
    <section class="slide" id="font-display-adoption">
        <div class="slide-content container">
            <div class="grid-2">
                <div style="display: flex; flex-direction: column; justify-content: center;">
                    <h2 class="reveal">Font-Display Reaches 42% on Mobile</h2>
                    <p class="reveal" style="margin-bottom: 2rem;">Mitigating the Flash of Invisible Text (FOIT)</p>
                    <ul class="bullet-list reveal">
                        <li><strong>Mobile Adoption:</strong> 42.5% (Up 61.0% since 2020)</li>
                        <li><strong>Desktop Adoption:</strong> 40.1% (Up 14.9% since 2020)</li>
                        <li style="margin-top: 1rem;"><strong>The UX Gap:</strong> Despite growth, more than half of pages globally still risk showing invisible text during web font loading.</li>
                    </ul>
                </div>
                <div class="reveal stat-card" style="padding: 4rem; text-align: center;">
                    <div class="stat-label" style="font-size: var(--h2-size);">Mobile Growth</div>
                    <div class="stat-value" style="color: var(--accent-success); font-size: 6rem; margin: 2rem 0;">+61%</div>
                    <div class="stat-desc" style="font-size: var(--body-size);">Significant relative improvement, yet massive room for industry-wide optimization remains.</div>
                </div>
            </div>
        </div>
    </section>

    <!-- Slide 8: Key Takeaways -->
    <section class="slide" id="key-takeaways">
        <div class="slide-content container">
            <h2 class="reveal">Key Takeaways</h2>
            <p class="reveal">Bigger Pages, Smarter Protocols, Stronger Security</p>
            <div class="stat-card reveal" style="margin-top: 2rem; padding: 3rem;">
                <ul class="bullet-list" style="gap: 1.8rem; font-size: 1.3rem;">
                    <li><strong>Weight Growth:</strong> Page weight continues to grow (~25%) driven by richer media and JS.</li>
                    <li><strong>Security Standard:</strong> HTTPS is effectively universal at 99%+.</li>
                    <li><strong>Protocol Shift:</strong> HTTP/3 support is the fastest-growing metric, approaching 40%.</li>
                    <li><strong>Network Efficiency:</strong> TCP connections are declining (down 15-27%) thanks to multiplexing, despite slight rises in total requests.</li>
                    <li><strong>UX Opportunity:</strong> Font-display adoption still has significant room to grow to prevent invisible text.</li>
                </ul>
            </div>
            <div class="reveal" style="margin-top: 3rem; text-align: center; color: var(--accent); font-weight: 800; font-size: var(--h3-size); font-family: var(--font-display);">
                Call to Action: Benchmark your sites against these baselines.
            </div>
        </div>
    </section>

    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;

                // Initialize slides state immediately for rendering engine
                if(this.slides.length > 0) {
                    this.slides[0].classList.add('visible');
                }

                this.setupIntersectionObserver();
                this.setupKeyboardNav();
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            this.currentSlide = Array.from(this.slides).indexOf(entry.target);
                        }
                    });
                }, { threshold: 0.1 }); // Lower threshold so it triggers earlier

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ') {
                        e.preventDefault();
                        this.nextSlide();
                    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                        e.preventDefault();
                        this.prevSlide();
                    }
                });
            }

            nextSlide() {
                if (this.currentSlide < this.slides.length - 1) {
                    this.currentSlide++;
                    this.slides[this.currentSlide].scrollIntoView({ behavior: 'auto' });
                }
            }

            prevSlide() {
                if (this.currentSlide > 0) {
                    this.currentSlide--;
                    this.slides[this.currentSlide].scrollIntoView({ behavior: 'auto' });
                }
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
</body>
</html>
